import torch
import torch.nn as nn
import torch.nn.functional as F
from einops import rearrange

class LinearAttention(nn.Module):
    def __init__(self, dim, heads=8):
        super().__init__()
        self.heads = heads
        self.scale = (dim // heads) ** -0.5
        self.to_qkv = nn.Linear(dim, dim * 3, bias=False)
        self.out_proj = nn.Linear(dim, dim)

    def forward(self, x):
        B, N, C = x.shape
        qkv = rearrange(self.to_qkv(x), "b n (h k qkv) -> b qkv h n k", h=self.heads)
        q, k, v = qkv[0], qkv[1], qkv[2]
        attn = torch.einsum("b h i d, b h j d-> b h i j", q, k) * self.scale
        attn = F.softmax(attn, dim=-1)
        out = torch.einsum("b h i j, b h j d-> b h i d", attn, v)
        out = rearrange(out, "b h n d -> b n (h d)")
        return self.out_proj(out)

class HierarchicalReasoning(nn.Module):
    def __init__(self, dim, depth=3):
        super().__init__()
        self.depth = depth
        self.layers = nn.ModuleList([
            nn.Sequential(
                nn.LayerNorm(dim),
                nn.GELU(),
                nn.Linear(dim, dim)
            ) for _ in range(depth)
        ])

    def forward(self, x):
        for layer in self.layers:
            x = x + layer(x)
        return x

class EarlyFusionEncoder(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.encoder = nn.TransformerEncoder(
            nn.TransformerEncoderLayer(d_model=dim, nhead=8), num_layers=1
        )

    def forward(self, attn_feat, hrm_feat):
        combined = torch.cat([attn_feat, hrm_feat], dim=-1)
        return self.encoder(combined)

class AttentionGate(nn.Module):
    def __init__(self, dim, threshold=0.5):
        super().__init__()
        self.threshold = threshold
        self.fc = nn.Linear(dim, 1)

    def forward(self, attn_map):
        gate = torch.sigmoid(self.fc(attn_map))
        mask = (gate > self.threshold).float()
        return mask

class DeltaNet(nn.Module):
    def __init__(self, dim, heads=8, depth=3):
        super().__init__()
        self.attn = LinearAttention(dim, heads)
        self.hrm = HierarchicalReasoning(dim, depth)
        self.fusion = EarlyFusionEncoder(dim)
        self.gate = AttentionGate(dim)
        self.out_proj = nn.Linear(dim, dim)

    def forward(self, x, **kwargs):
        # Linear attention path
        attn_feat = self.attn(x)
        # Hierarchical reasoning path
        hrm_feat = self.hrm(x)
        # Adaptive gating: mask HRM output where attention confidence low
        mask = self.gate(attn_feat)
        hrm_feat = hrm_feat * mask
        # Early fusion via shared encoder
        fused = self.fusion(attn_feat, hrm_feat)
        return self.out_proj(fused)

